def plan_key(building, plan):
    if building.startswith('Griffis'):
        return G[plan.replace(' Platinum', '')]
    return W[plan]

if __name__ == '__main__':
    here = pathlib.Path(__file__).parent
    labels = json.loads((here / 'plan-labels.json').read_text())['plans']
    # Remember which image each plan was drawn from, so a changed image can be flagged.
    site = json.loads(pathlib.Path(sys.argv[1]).read_text()) if len(sys.argv) > 1 else None
    img = {}
    if site:
        bname = {b['id']: b['name'] for b in site['buildings']}
        img = {(bname[p['building_id']], p['name']): p['image_url'] for p in site['floorPlans']}
    plans = [{'building': p['building'], 'plan': p['plan'], 'drawing': plan_key(p['building'], p['plan']),
              'image_url': img.get((p['building'], p['plan']))} for p in labels]
    out = {'drawn_on': '2026-11-01', 'drawn_by': 'Claude (traced by eye from each plan image)', 'status': 'pending review',
           'note': 'Coordinates are in the source image pixels; rectangles are [x1, y1, x2, y2]; {"p": [...]} is a polygon.',
           'drawings': D, 'plans': plans}
    (here / 'plan-drawings.json').write_text(json.dumps(out, indent=1))
    print(len(D), 'drawings for', len(plans), 'plans')
